#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-05
# State-link probe campaign (image fishwait24): what do the probes give and what do they cost?
# Five configurations of the same Autoware replay, interleaved over PASSES passes (host in split mode):
#   base   untraced
#   off    FISH tier max, none of the new events            (= the fishwait23 configuration on the new image)
#   s123   + message retention (1, 2) + leading stamp (3)
#   s123A  + further Time / UUID fields (A)
#   all    + lock shim (C)
# Usage: PASSES=3 scripts/state_probe_campaign.sh <log_dir>   → <log_dir>/night_runs.txt lists "<label> <campaign dir>"
set -u
cd "$(dirname "$0")/.."
LD=${1:?log dir}; PASSES=${PASSES:-3}; CONFIGS=${CONFIGS:-"base off s123 s123A all"}
IMG=${IMG:-autoware-dev-trt-a1000-fishwait24:latest}
E1=ros2:fish_msg_retain,ros2:fish_msg_release; E3=ros2:fish_msg_type,ros2:fish_msg_stamp; EA=ros2:fish_msg_ids; EC=ros2:fish_lock,ros2:fish_lock_site
plan() {
  for p in $(seq 1 "$PASSES"); do
    for c in $CONFIGS; do
      case $c in
        base)  echo "base_$p IMG=$IMG MODES=baseline" ;;
        off)   echo "off_$p IMG=$IMG" ;;
        s123)  echo "s123_$p IMG=$IMG FISH_EXTRA_EVENTS=$E1,$E3" ;;
        s123A) echo "s123A_$p IMG=$IMG FISH_EXTRA_EVENTS=$E1,$E3,$EA" ;;
        all)   echo "all_$p IMG=$IMG FISH_EXTRA_EVENTS=$E1,$E3,$EA,$EC FISH_LOCK_SHIM=1" ;;
      esac
    done
  done
}
mkdir -p "$LD"; plan > "$LD/plan.txt"
bash scripts/night_runs.sh "$LD" < "$LD/plan.txt"
